{'content': '// Chess Rook Piece
// Dimensions in mm

$fn = 64;

module rook() {
    // Base platform
    base();

    // Main body column
    translate([0, 0, 5])
        body();

    // Top platform / battlement area
    translate([0, 0, 55])
        top_section();

    // Battlements (crenellations)
    translate([0, 0, 62])
        battlements();
}

module base() {
    // Wide circular base with beveled edge
    hull() {
        cylinder(h = 1, r = 18, center = false);
        translate([0, 0, 1])
            cylinder(h = 4, r = 16, center = false);
    }

    // Base ring detail
    translate([0, 0, 5])
        cylinder(h = 2, r1 = 16, r2 = 13, center = false);

    // Second tier base
    translate([0, 0, 7])
        cylinder(h = 2, r1 = 13, r2 = 11, center = false);
}

module body() {
    // Lower collar
    cylinder(h = 3, r1 = 12, r2 = 10.5, center = false);

    // Main tapered column
    translate([0, 0, 3])
        cylinder(h = 35, r1 = 10.5, r2 = 9, center = false);

    // Upper collar ring 1
    translate([0, 0, 38])
        cylinder(h = 2, r1 = 9, r2 = 10, center = false);

    // Upper collar ring 2
    translate([0, 0, 40])
        cylinder(h = 2, r1 = 10, r2 = 11, center = false);

    // Neck
    translate([0, 0, 42])
        cylinder(h = 5, r1 = 11, r2 = 12, center = false);

    // Transition to top
    translate([0, 0, 47])
        cylinder(h = 3, r1 = 12, r2 = 13, center = false);
}

module top_section() {
    // Top platform - wider flat area
    cylinder(h = 3, r1 = 13, r2 = 14, center = false);

    // Rim
    translate([0, 0, 3])
        cylinder(h = 4, r = 14, center = false);
}

module battlements() {
    num_merlons = 5;
    merlon_width = 8;    // angular width in degrees
    merlon_height = 8;
    wall_thickness = 4;
    outer_r = 14;
    inner_r = outer_r - wall_thickness;

    // Outer wall ring (the base of battlements)
    difference() {
        cylinder(h = merlon_height, r = outer_r, center = false);

        // Hollow inside
        translate([0, 0, -1])
            cylinder(h = merlon_height + 2, r = inner_r, center = false);

        // Cut the crenels (gaps between merlons)
        for (i = [0 : num_merlons - 1]) {
            angle = i * (360 / num_merlons);
            // Each crenel is a gap - we cut from half height up
            rotate([0, 0, angle])
                translate([0, 0, merlon_height * 0.45])
                    crenel_cut(outer_r, inner_r, merlon_height);
        }
    }
}

module crenel_cut(outer_r, inner_r, h) {
    // Cut a rectangular notch in the wall
    crenel_angular_width = 26; // degrees

    rotate([0, 0, -crenel_angular_width/2])
    linear_extrude(height = h)
        difference() {
            // Outer arc
            intersection() {
                circle(r = outer_r + 1);
                pie_slice(outer_r + 1, crenel_angular_width);
            }
            // Inner arc
            circle(r = inner_r - 0.5);
        }
}

module pie_slice(r, angle) {
    // Create a 2D pie/wedge shape
    intersection() {
        circle(r = r);
        polygon(points = [
            [0, 0],
            [r * 2, 0],
            [r * 2 * cos(angle), r * 2 * sin(angle)],
            [0, 0]
        ]);
    }
}

// Render the rook
rook();
