        rotate_extrude()
            translate([12, 1.5, 0])
                circle(r = 1.5);

    // Transition to body
    translate([0, 0, 6])
        cylinder(h = 3, r1 = 12.5, r2 = 10);
}

module body() {
    // Main tapered shaft
    cylinder(h = 38, r1 = 10, r2 = 8.5);

    // Subtle middle ring
    translate([0, 0, 18])
        rotate_extrude()
            translate([10, 0, 0])
                scale([1, 1.5])
                    circle(r = 0.6);

    // Upper collar area
    translate([0, 0, 38])
        cylinder(h = 2, r1 = 8.5, r2 = 9.5);

    translate([0, 0, 40])
        rotate_extrude()
            translate([9.5, 1, 0])
                circle(r = 1);

    translate([0, 0, 41])
        cylinder(h = 2, r1 = 10, r2 = 11);

    translate([0, 0, 43])
        cylinder(h = 3, r1 = 11, r2 = 11.5);

    // Upper ring detail
    translate([0, 0, 46])
        rotate_extrude()
            translate([11.5, 1, 0])
                circle(r = 1);

    translate([0, 0, 47])
        cylinder(h = 2, r1 = 12, r2 = 13);
}

module crown() {
    num_merlons = 5;
    merlon_angular = 360 / num_merlons; // 72 degrees per segment
    crenel_ratio = 0.45; // portion of each segment that is a gap

    outer_r = 14;
    inner_r = 10;
    wall_height = 10;
    crenel_depth = 5; // how much of the top is cut away for crenels

    difference() {
        union() {
            // Base platform of crown
            cylinder(h = 2, r1 = 13, r2 = outer_r);

            // Crown wall
            translate([0, 0, 2])
            difference() {
                cylinder(h = wall_height, r = outer_r);
                translate([0, 0, -1])
                    cylinder(h = wall_height + 2, r = inner_r);
            }
        }

        // Cut crenels (the gaps between merlons)
        for (i = [0 : num_merlons - 1]) {
            angle = i * merlon_angular + merlon_angular * (1 - crenel_ratio) / 2;
            rotate([0, 0, angle])
                translate([0, 0, 2 + wall_height - crenel_depth])
                    crenel_cut(outer_r + 1, inner_r - 1, crenel_depth + 1, merlon_angular * crenel_ratio);
        }

        // Inner hollow bowl shape at top
        translate([0, 0, 2])
            cylinder(h = 1.5, r1 = 8, r2 = inner_r);
    }
}

module crenel_cut(outer_r, inner_r, h, angle_span) {
    // Wedge-shaped cut through the wall
    linear_extrude(height = h)
        difference() {
            // Pie slice at outer radius
            pie_slice(outer_r, angle_span);
            // Remove inner part
            circle(r = inner_r);
        }
}

module pie_slice(r, angle) {
    if (angle < 180) {
        intersection() {
            circle(r = r);
            polygon(points = [
                [0, 0],
                [r * 1.5, 0],
                [r * 1.5 * cos(angle), r * 1.5 * sin(angle)],
                [0, 0]
            ]);
        }
    }
}

// Render the rook
rook();
'}

